CREATE TABLE IF NOT EXISTS property_intelligence.illegal_schemes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(300) NOT NULL, location varchar(300) NULL, name_key varchar(300) NOT NULL UNIQUE, regulator varchar(10) NOT NULL DEFAULT 'CDA', city varchar(100) NOT NULL DEFAULT 'Islamabad', source_url text NOT NULL, listed_as_of date NOT NULL, is_active boolean NOT NULL DEFAULT true, record_type varchar(10) NOT NULL DEFAULT 'FACT', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now())
